using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BlueWispFrameEvents {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/BlueWisp/V3");
 static Type utility,windowType;static EditorWindow window,focused;static bool created,background,paused;static List<GameObject> clones=new List<GameObject>(),hidden=new List<GameObject>();static List<bool> active=new List<bool>();static List<object> reports=new List<object>();static int count=1,stage,attempts;static double begin;
 static object Field(object o,string n)=>o.GetType().GetField(n,F)?.GetValue(o);
 static void Disable(){windowType.GetMethod("DisableFrameDebugger",F).Invoke(window,null);EditorApplication.isPaused=false;}
 static void Setup(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();for(int i=0;i<count;i++){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/BlueWisp/V3/Prefabs/VFX_BlueWisp_V3_Loop.prefab"));g.name="BlueWisp_FrameProbe_"+i;g.transform.position=new Vector3(0,1.68f,0);clones.Add(g);}stage=0;begin=Time.timeAsDouble;}
 static void Finish(string error=null){EditorApplication.update-=Tick;try{Disable();}catch{}foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);for(int i=0;i<hidden.Count;i++)if(hidden[i]!=null)hidden[i].SetActive(active[i]);Application.runInBackground=background;EditorApplication.isPaused=paused;if(created&&window!=null)window.Close();if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Out,"FrameDebuggerEvents.json"),JsonConvert.SerializeObject(new{error,method="Official FrameDebuggerWindow API, isolated shared workbench, 1/8 actual Play Mode instances, separate from performance timing",reports,limitation="Event metadata alone cannot establish renderer merges or batch-break reasons. Details are available only when GetFrameEventData succeeds.",restored=true},Formatting.Indented));}
 static void Tick(){try{
  if(!Application.isPlaying){Finish("Play Mode stopped");return;}
  if(stage==0&&Time.timeAsDouble-begin>.8){EditorApplication.isPaused=true;windowType.GetMethod("EnableFrameDebugger",F).Invoke(window,null);stage=1;begin=EditorApplication.timeSinceStartup;attempts=0;return;}
  if(stage==1&&EditorApplication.timeSinceStartup-begin>.7){var events=(Array)utility.GetMethod("GetFrameEvents",F).Invoke(null,null);if((events==null||events.Length==0)&&attempts++<2){begin=EditorApplication.timeSinceStartup;return;}var list=new List<object>();int tried=0;
   if(events!=null)for(int i=0;i<events.Length;i++){var evt=events.GetValue(i);var obj=Field(evt,"m_Obj") as UnityEngine.Object;string type=Field(evt,"m_Type")?.ToString();if(type==null)continue;bool ok=false;object detail=null;
    if(obj!=null&&tried++<4)try{var dt=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerEventData");var data=Activator.CreateInstance(dt,true);ok=(bool)utility.GetMethod("GetFrameEventData",F).Invoke(null,new[]{(object)i,data});if(ok)detail=new{shader=Field(data,"m_RealShaderName")?.ToString(),pass=Field(data,"m_PassName")?.ToString(),draws=Field(data,"m_DrawCallCount"),instances=Field(data,"m_InstanceCount"),vertices=Field(data,"m_VertexCount")};}catch{}
    list.Add(new{index=i,type,obj=obj==null?null:obj.name,info=utility.GetMethod("GetFrameEventInfoName",F).Invoke(null,new object[]{i})?.ToString(),dataOk=ok,detail});}
   reports.Add(new{instances=count,totalEvents=events?.Length??0,events=list,particles=clones.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>()).Sum(p=>p.particleCount)});Disable();if(count==1){count=8;Setup();}else Finish();
  }
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||SceneManager.GetActiveScene().path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong scope/state");utility=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerUtility");windowType=typeof(Editor).Assembly.GetType("UnityEditor.FrameDebuggerWindow");focused=EditorWindow.focusedWindow;background=Application.runInBackground;paused=EditorApplication.isPaused;Application.runInBackground=true;window=Resources.FindObjectsOfTypeAll(windowType).Cast<EditorWindow>().FirstOrDefault();created=window==null;if(created)window=EditorWindow.GetWindow(windowType);foreach(var g in SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.GetComponent<Camera>()==null)){hidden.Add(g);active.Add(g.activeSelf);g.SetActive(false);}Setup();EditorApplication.update+=Tick;return "Bounded 1/8-instance frame-event capture scheduled.";}
}
